import { ChevronDown, CircleHelp, Lightbulb, SearchCheck } from "lucide-react";
import type { Analysis, ScorePart } from "../api";

// Explanations use only saved score components and missing skills.
// No unverified claims about the candidate are generated by this component.
function explain(part: ScorePart): string {
  const category = part.category.toLowerCase();
  if (category.includes("skill") || category.includes("technical"))
    return "One or more JD technologies were not clearly evidenced in the source document.";
  if (category.includes("experience"))
    return "The recorded professional experience did not fully meet the rule-based JD criteria.";
  if (category.includes("responsib"))
    return "The resume did not explicitly support every responsibility matched from the JD.";
  if (category.includes("project"))
    return "Relevant project evidence was limited or not clearly identifiable by this parser.";
  if (category.includes("qualif") || category.includes("education"))
    return "Some requested qualification evidence was not recognized in the original resume.";
  if (category.includes("readab") || category.includes("format"))
    return "Some document content could not be evaluated reliably by the baseline reader.";
  return "This component awarded fewer points than its maximum under the current scoring rules.";
}

export default function ScoreRecommendations({ result }: { result: Analysis }) {
  const gaps = result.breakdown
    .filter(part => part.applicable && part.weight > 0 && part.awarded < part.weight)
    .map(part => ({ ...part, lost: Math.max(0, part.weight - part.awarded) }))
    .sort((a, b) => b.lost - a.lost);
  return (
    <section className="waah-recommendations" aria-label="Recommendations and score explanations">
      <div className="waah-rec-heading">
        <span className="waah-rec-icon"><Lightbulb size={19} aria-hidden="true" /></span>
        <div>
          <h4>Recommendations</h4>
          <p>Review the specific gaps found by this evaluation before changing the resume.</p>
        </div>
      </div>
      <details className="waah-rec-disclosure">
        <summary>
          <span><CircleHelp size={18} aria-hidden="true" /> Why is the score lower?</span>
          <ChevronDown size={19} className="waah-rec-chevron" aria-hidden="true" />
        </summary>
        <div className="waah-rec-content">
          {result.missingSkills.length > 0 && (
            <div className="waah-rec-item">
              <strong>Requirements not evidenced</strong>
              <p>{result.missingSkills.join(", ")}</p>
              <small>Only add evidence for skills or experience the candidate genuinely has.</small>
            </div>
          )}
          {gaps.length > 0 ? gaps.map(gap => (
            <div className="waah-rec-item" key={gap.category}>
              <div className="waah-rec-item-head">
                <strong>{gap.category}</strong>
                <span>{gap.awarded} / {gap.weight} points</span>
              </div>
              <p>{explain(gap)}</p>
            </div>
          )) : result.missingSkills.length === 0 ? (
            <div className="waah-rec-item"><strong>No specific scoring gaps identified</strong>
              <p>The baseline rules found no deducted applicable score components. A human should still review the original resume.</p>
            </div>
          ) : null}
          <p className="waah-rec-footnote"><SearchCheck size={15} aria-hidden="true" />
            Explanations reflect the estimated scoring rules, not proof the candidate lacks a qualification.
          </p>
        </div>
      </details>
    </section>
  );
}
